export default GamesHub;

import React, { useState } from 'react';
import { Order, Product, StaffMember } from '../types';
import { GoogleGenAI } from "@google/genai";

interface InsightsViewProps {
    filteredOrders: Order[];
    products: Product[];
    staff: StaffMember[];
}

const InsightsView: React.FC<InsightsViewProps> = ({ filteredOrders, products, staff }) => {
    const [query, setQuery] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [analysis, setAnalysis] = useState<string | null>(null);
    const [suggestedQuestions] = useState([
        "C'è qualche prodotto in esaurimento?",
        "Chi ha lavorato meglio oggi?",
        "Qual è l'orario di un turno 12/24?",
        "Quali sono i gradi VVF?",
        "Dammi una ricetta per un cocktail"
    ]);

    const handleQuery = async (userQuery: string) => {
        setIsLoading(true);
        setError(null);
        setAnalysis(null);

        try {
            const dataSummary = `
                DATI BAR ATTUALI (Filtro Attivo):
                - Numero transazioni: ${filteredOrders.length}
                - Incasso totale periodo: €${filteredOrders.reduce((sum, o) => sum + o.total, 0).toFixed(2)}
                - Data Inizio Filtro: ${filteredOrders.length > 0 ? new Date(filteredOrders[filteredOrders.length - 1].timestamp).toLocaleDateString('it-IT') : 'N/D'}
                - Data Fine Filtro: ${filteredOrders.length > 0 ? new Date(filteredOrders[0].timestamp).toLocaleDateString('it-IT') : 'N/D'}
                - Lista Prodotti nel sistema: ${products.map(p => `${p.name} (Stock: ${p.stock})`).join(', ')}
                - Personale: ${staff.map(s => `${s.name} (Turno ${s.shift})`).join(', ')}
            `;

            const detailedOrders = filteredOrders.slice(0, 20).map(o => ({
                date: new Date(o.timestamp).toLocaleDateString('it-IT'),
                time: new Date(o.timestamp).toLocaleTimeString('it-IT'),
                total: o.total,
                staff: o.staffName,
                items: o.items.map(i => `${i.quantity}x ${i.product.name}`).join(', ')
            }));

            const fullPrompt = `
Sei Mario, un vigile del fuoco veterano e simpatico, ma anche l'assistente virtuale del Bar VVF.
Il tuo compito è rispondere alle domande dell'utente. 

Hai due ruoli principali:
1. **Analista del Bar**: Usa i dati forniti qui sotto per rispondere a domande su vendite, prodotti, incassi e personale.
2. **Esperto VVF**: Usa la tua conoscenza generale (pre-addestrata) per rispondere a domande su turni, regolamenti, gradi, normative, procedure operative, mezzi di soccorso, uffici e vita di caserma.

DATI BAR DISPONIBILI:
${dataSummary}

ULTIMI ORDINI (Campione):
${JSON.stringify(detailedOrders, null, 2)}

DOMANDA UTENTE: "${userQuery}"

LINEE GUIDA RISPOSTA:
- Parla come un collega pompiere esperto e amichevole (usa termini come "collega", "ragazzi", "capo").
- Se la domanda riguarda il bar, usa i dati forniti. Sii preciso sui numeri.
- Se la domanda riguarda i VVF o altro, rispondi con competenza.
- Se ti chiedono un consiglio, sii propositivo.
- Sii conciso ma esaustivo.
- Usa qualche emoji a tema (🚒, 🔥, ☕).
`;

            const apiKey = process.env.API_KEY;
            if (!apiKey) {
                throw new Error("API Key mancante.");
            }

            const ai = new GoogleGenAI({ apiKey });
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: fullPrompt,
            });

            if (response.text) {
                setAnalysis(response.text);
            } else {
                throw new Error("Mario è impegnato in intervento e non ha risposto.");
            }

        } catch (e) {
            console.error(e);
            setError(e instanceof Error ? e.message : "Errore di comunicazione con Mario.");
        } finally {
            setIsLoading(false);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (query.trim()) {
            handleQuery(query);
        }
    };

    const handleSuggestedClick = (question: string) => {
        setQuery(question);
        handleQuery(question);
    };

    return (
        <div className="max-w-4xl mx-auto">
            <div className="bg-white p-6 rounded-2xl shadow-xl border-t-4 border-red-600 relative overflow-hidden">
                <div className="flex items-start gap-4 mb-6">
                    <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center border-2 border-red-200 shadow-sm flex-shrink-0">
                        <span className="text-4xl filter drop-shadow-sm">👨‍🚒</span>
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Chiedi a Mario</h2>
                        <p className="text-slate-500 font-medium text-sm leading-tight">Il tuo assistente virtuale VVF. Chiedimi del bar, dei turni o di normative!</p>
                    </div>
                </div>

                <form onSubmit={handleSubmit} className="flex gap-2 mb-6">
                    <input
                        type="text"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        placeholder="Es. Quanti caffè abbiamo venduto? Oppure: Come funziona il salto?"
                        className="flex-grow bg-slate-50 text-slate-800 border border-slate-200 rounded-xl p-4 focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-transparent shadow-inner font-medium placeholder:text-slate-400"
                        disabled={isLoading}
                    />
                    <button type="submit" disabled={isLoading || !query.trim()} className="bg-red-600 text-white font-bold py-3 px-6 rounded-xl hover:bg-red-700 disabled:bg-slate-300 transition-all shadow-md active:translate-y-0.5">
                        {isLoading ? (
                            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                        )}
                    </button>
                </form>

                <div className="flex flex-wrap gap-2 mb-6">
                    {suggestedQuestions.map(q => (
                        <button key={q} onClick={() => handleSuggestedClick(q)} disabled={isLoading} className="text-xs font-bold bg-slate-100 text-slate-600 px-3 py-1.5 rounded-lg hover:bg-red-50 hover:text-red-600 hover:border-red-200 border border-transparent transition-all disabled:opacity-50">
                            {q}
                        </button>
                    ))}
                </div>

                {error && (
                    <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-4 rounded-r-lg text-sm mb-4 animate-fade-in">
                        <p className="font-bold flex items-center gap-2">⚠️ Errore Radio</p>
                        <p>{error}</p>
                    </div>
                )}

                {analysis && (
                    <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200 animate-fade-in shadow-inner relative">
                        <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-red-400 to-orange-400 rounded-l-2xl"></div>
                        <h3 className="text-sm font-black text-slate-400 uppercase mb-3 tracking-widest">Risposta di Mario</h3>
                        <div className="prose prose-sm prose-slate max-w-none whitespace-pre-wrap font-medium text-slate-700">
                            {analysis}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default InsightsView;

import React, { useState, useEffect } from 'react';
import { TillColors, ShiftSettings } from '../types';
import { BackArrowIcon, CalendarIcon } from './Icons';

interface ShiftCalendarProps {
    onGoBack: () => void;
    tillColors: TillColors;
    shiftSettings?: ShiftSettings;
}

const ShiftCalendar: React.FC<ShiftCalendarProps> = ({ onGoBack, tillColors, shiftSettings }) => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [highlightShift, setHighlightShift] = useState<'A' | 'B' | 'C' | 'D' | null>(null);
    const [userSubGroup, setUserSubGroup] = useState<number | 'none'>('none');

    // ANCORA DINAMICA
    const getShiftsForDate = (date: Date) => {
        const anchorDateStr = shiftSettings?.anchorDate || new Date().toISOString().split('T')[0];
        const anchorShift = shiftSettings?.anchorShift || 'b';

        const anchorDate = new Date(anchorDateStr);
        anchorDate.setHours(12, 0, 0, 0); // Fix DST

        const targetDate = new Date(date);
        targetDate.setHours(12, 0, 0, 0); // Fix DST

        const diffTime = targetDate.getTime() - anchorDate.getTime();
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24)); // Usa round

        const shifts = ['A', 'B', 'C', 'D'];
        const anchorIndex = shifts.indexOf(anchorShift.toUpperCase());

        // Calcolo Turno Giorno
        let dayIndex = (anchorIndex + diffDays) % 4;
        if (dayIndex < 0) dayIndex += 4;

        // VVF Standard: 12-24 12-48.
        let nightIndex = dayIndex - 1;
        if (nightIndex < 0) nightIndex += 4;

        return {
            day: shifts[dayIndex],
            night: shifts[nightIndex]
        };
    };

    // CALCOLO SOTTOGRUPPO DI SALTO (1-8)
    const getRestingSubGroup = (shift: string, date: Date, type: 'day' | 'night') => {
        if (!shiftSettings?.rcAnchorDate) return null;

        const anchorDate = new Date(shiftSettings.rcAnchorDate);
        anchorDate.setHours(12, 0, 0, 0);

        // Data EFFICACE per il calcolo del ciclo.
        // Se è turno di GIORNO, la data è quella corrente.
        // Se è turno di NOTTE, la data efficace è quella del GIORNO PRECEDENTE (inizio del blocco lavorativo 12-24).
        const effectiveDate = new Date(date);
        effectiveDate.setHours(12, 0, 0, 0);
        if (type === 'night') {
            effectiveDate.setDate(effectiveDate.getDate() - 1);
        }

        // Calcolo Base Date
        const shifts = ['A', 'B', 'C', 'D'];
        const shiftIndex = shifts.indexOf(shift.toUpperCase());
        const anchorShiftIndex = shifts.indexOf((shiftSettings.rcAnchorShift || 'A').toUpperCase());

        const shiftOffset = shiftIndex - anchorShiftIndex;

        const baseDateForShift = new Date(anchorDate);
        baseDateForShift.setDate(baseDateForShift.getDate() + shiftOffset);

        const diffTime = effectiveDate.getTime() - baseDateForShift.getTime();
        const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));

        const cycles = Math.floor(diffDays / 4);
        const anchorSubGroup = shiftSettings.rcAnchorSubGroup || 1;

        let currentSubGroup = (anchorSubGroup + cycles) % 8;
        if (currentSubGroup <= 0) currentSubGroup += 8;

        return currentSubGroup;
    };

    const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
    const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay();
    const startingBlankDays = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

    const changeMonth = (delta: number) => {
        const newDate = new Date(currentDate);
        newDate.setMonth(newDate.getMonth() + delta);
        setCurrentDate(newDate);
    };

    const jumpToToday = () => setCurrentDate(new Date());

    const monthNames = ["Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno", "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"];

    const defaultColors: {[key: string]: string} = {
        'TA': '#ef4444', // Red
        'TB': '#3b82f6', // Blue
        'TC': '#22c55e', // Green
        'TD': '#eab308'  // Yellow
    };

    const getShiftColor = (shift: string) => {
        const tillId = `T${shift}`;
        return tillColors[tillId] || defaultColors[tillId] || '#94a3b8';
    };

    // Helper per renderizzare la cella turno
    const renderShiftRow = (shift: string, type: 'day' | 'night', isDimmed: boolean, date: Date) => {

        const restingGroup = getRestingSubGroup(shift, date, type);
        const isMyRest = userSubGroup !== 'none' && restingGroup === userSubGroup;
        const showAsRest = isMyRest;

        const color = getShiftColor(shift);
        const icon = showAsRest ? '💤' : (type === 'day' ? '☀️' : '🌙');
        const labelText = showAsRest ? 'SALTO' : (type === 'day' ? 'Giorno' : 'Notte');
        const displayShift = restingGroup ? `${shift}${restingGroup}` : shift;

        // Colore Sfondo
        const bgColor = showAsRest 
            ? 'bg-purple-100 border-purple-200' 
            : (type === 'day' ? 'bg-orange-50/50 border-orange-100' : 'bg-slate-100/50 border-slate-100');

        // Badge a destra
        const badgeStyle = showAsRest ? { backgroundColor: '#9333ea' } : { backgroundColor: color };
        const textStyle = showAsRest ? { color: '#9333ea' } : { color: color };

        return (
            <div 
                className={`
                    rounded shadow-sm border overflow-hidden
                    flex items-center justify-center md:justify-between
                    transition-all duration-300 w-full
                    ${bgColor}
                    ${isDimmed ? 'opacity-10 grayscale' : 'opacity-100'}
                `}
            >
                {/* DESKTOP VIEW */}
                <div className="hidden md:flex items-center w-full justify-between px-2 py-1">
                    <span className="text-xs font-bold text-slate-600 flex items-center gap-1">
                        <span className="text-lg leading-none">{icon}</span> 
                        {labelText}
                    </span>
                    <span 
                        className="font-black text-xs px-2 rounded text-white shadow-sm min-w-[2.5em] text-center"
                        style={badgeStyle}
                    >
                        {showAsRest ? `S-${restingGroup}` : displayShift}
                    </span>
                </div>

                {/* MOBILE VIEW FIX - Flex Column per centrare tutto */}
                <div className="md:hidden flex flex-col items-center justify-center w-full py-1">
                    <span className="text-[10px] opacity-60 leading-none mb-0.5">
                        {icon}
                    </span>
                    <span className="font-black text-sm leading-none tracking-tighter" style={textStyle}>
                        {showAsRest ? 'S' : displayShift}
                    </span>
                </div>
            </div>
        );
    };

    return (
        <div className="flex flex-col min-h-screen bg-slate-50 font-sans">
            <header className="bg-white shadow-sm p-4 flex justify-between items-center sticky top-0 z-10">
                <button
                    onClick={onGoBack}
                    className="flex items-center gap-2 px-4 py-2 rounded-full text-slate-500 hover:bg-slate-100 transition-colors"
                >
                    <BackArrowIcon className="h-5 w-5" />
                    <span className="font-bold text-sm hidden md:block">Indietro</span>
                </button>
                <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                    <CalendarIcon className="h-6 w-6 text-primary" /> Turnario VVF
                </h1>
                <button 
                    onClick={jumpToToday}
                    className="text-xs font-bold text-primary bg-orange-50 px-3 py-1 rounded-full border border-orange-100 hover:bg-orange-100"
                >
                    Oggi
                </button>
            </header>

            <main className="flex-grow p-2 md:p-8 max-w-5xl mx-auto w-full">

                {/* Controlli e Filtri */}
                <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-6 flex flex-col md:flex-row justify-between items-center gap-4">
                    <div className="flex items-center gap-4">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-slate-100 rounded-full">←</button>
                        <h2 className="text-xl md:text-2xl font-black text-slate-800 uppercase w-48 text-center">
                            {monthNames[currentDate.getMonth()]} <span className="text-slate-400 font-medium">{currentDate.getFullYear()}</span>
                        </h2>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-slate-100 rounded-full">→</button>
                    </div>

                    <div className="flex flex-col md:flex-row gap-4 items-center">
                        <div className="flex gap-2 items-center">
                            <span className="text-[10px] md:text-xs font-bold text-slate-400 uppercase mr-2">Turno:</span>
                            {['A', 'B', 'C', 'D'].map(shift => (
                                <button
                                    key={shift}
                                    onClick={() => setHighlightShift(highlightShift === shift ? null : shift as any)}
                                    className={`w-8 h-8 rounded-full font-bold text-xs flex items-center justify-center transition-all shadow-sm ${highlightShift === shift ? 'ring-2 ring-offset-2 ring-slate-400 scale-110' : 'opacity-70 hover:opacity-100'}`}
                                    style={{ backgroundColor: getShiftColor(shift), color: '#fff' }}
                                >
                                    {shift}
                                </button>
                            ))}
                        </div>

                        <div className="flex items-center gap-2 border-l pl-4 border-slate-200">
                             <span className="text-[10px] md:text-xs font-bold text-slate-400 uppercase">Il mio Gruppo:</span>
                             <select 
                                value={userSubGroup} 
                                onChange={(e) => setUserSubGroup(e.target.value === 'none' ? 'none' : parseInt(e.target.value))}
                                className="bg-purple-50 border border-purple-200 text-purple-700 font-bold text-xs rounded px-2 py-1"
                             >
                                <option value="none">Nessuno</option>
                                {[1,2,3,4,5,6,7,8].map(n => <option key={n} value={n}>{n}</option>)}
                             </select>
                        </div>
                    </div>
                </div>

                {/* Griglia Calendario */}
                <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
                    <div className="grid grid-cols-7 bg-slate-100 border-b border-slate-200">
                        {['Lun', 'Mar', 'Mer', 'Gio', 'Ven', 'Sab', 'Dom'].map((d, i) => (
                            <div key={i} className={`py-3 text-center text-[10px] md:text-xs font-black uppercase ${i===6 ? 'text-red-500' : 'text-slate-500'}`}>
                                {d}
                            </div>
                        ))}
                    </div>

                    <div className="grid grid-cols-7 auto-rows-fr">
                        {Array.from({ length: startingBlankDays }).map((_, i) => (
                            <div key={`blank-${i}`} className="bg-slate-50/50 border-b border-r border-slate-100 min-h-[100px] md:min-h-[120px]"></div>
                        ))}

                        {Array.from({ length: daysInMonth }).map((_, i) => {
                            const dayNum = i + 1;
                            const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), dayNum);
                            const shifts = getShiftsForDate(date);
                            const isToday = new Date().toDateString() === date.toDateString();

                            const isFilterActive = highlightShift !== null;
                            const isDayDimmed = isFilterActive && shifts.day !== highlightShift;
                            const isNightDimmed = isFilterActive && shifts.night !== highlightShift;

                            return (
                                <div 
                                    key={dayNum} 
                                    className={`
                                        relative border-b border-r border-slate-100 min-h-[100px] md:min-h-[120px] p-1 md:p-2 flex flex-col gap-1 transition-all duration-300
                                        ${isToday ? 'bg-green-50 border-green-400 ring-1 ring-inset ring-green-500 shadow-md z-10' : 'bg-white hover:bg-slate-50'}
                                    `}
                                >
                                    <div className="flex justify-between items-start mb-1">
                                        <span className={`text-xs md:text-sm font-bold ${isToday ? 'text-green-800' : 'text-slate-700'}`}>{dayNum}</span>
                                        {isToday && <span className="text-[8px] md:text-[9px] font-black text-green-700 uppercase bg-green-200 px-1 rounded hidden md:inline">OGGI</span>}
                                    </div>

                                    <div className="flex flex-col gap-1 flex-grow justify-center">
                                        {renderShiftRow(shifts.day, 'day', isDayDimmed, date)}
                                        {renderShiftRow(shifts.night, 'night', isNightDimmed, date)}
                                    </div>

                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="mt-6 text-center text-xs text-slate-400">
                    <p>Schema turni perpetuo VVF 12-24 12-48 • Rotazione Salto 1-8</p>
                    {shiftSettings?.rcAnchorDate && <p className="mt-1 opacity-50">Salto calibrato su: {new Date(shiftSettings.rcAnchorDate).toLocaleDateString()} = Turno {shiftSettings.rcAnchorShift} (Gruppo {shiftSettings.rcAnchorSubGroup})</p>}
                </div>
            </main>
        </div>
    );
};

