import React, { useState, useMemo } from 'react';
import { Order, CashMovement } from '../types';
import firebase from 'firebase/compat/app';
import { TrashIcon } from './Icons';

interface CashManagementProps {
    orders: Order[];
    movements: CashMovement[];
    onAddMovement: (m: Omit<CashMovement, 'id'>) => Promise<void>;
    onUpdateMovement: (m: CashMovement) => Promise<void>;
    onDeleteMovement: (id: string, email: string) => Promise<void>;
    onPermanentDeleteMovement: (id: string) => Promise<void>;
    onResetCash: (type: 'bar' | 'games') => Promise<void>;
    isSuperAdmin: boolean;
    currentUser: firebase.User | null;
}

const CashManagement: React.FC<CashManagementProps> = ({ orders, movements, onAddMovement, onUpdateMovement, onDeleteMovement, onPermanentDeleteMovement, onResetCash, isSuperAdmin, currentUser }) => {
    const [amount, setAmount] = useState('');
    const [reason, setReason] = useState('');
    const [miscAmount, setMiscAmount] = useState('');
    const [miscReason, setMiscReason] = useState('');

    // --- SALDO BAR ---
    const activeOrders = useMemo(() => orders.filter(o => !o.isDeleted), [orders]);
    const salesRevenue = activeOrders.reduce((sum, o) => sum + o.total, 0) || 0;

    const activeMovements = useMemo(() => movements.filter(m => !m.isDeleted), [movements]);
    const cashMovementsBar = useMemo(() => activeMovements.filter(m => m.category === 'bar' || !m.category), [activeMovements]);
    const deposits = cashMovementsBar.filter(m => m.type === 'deposit').reduce((sum, m) => sum + m.amount, 0) || 0;
    const withdrawals = cashMovementsBar.filter(m => m.type === 'withdrawal').reduce((sum, m) => sum + m.amount, 0) || 0;
    const operationalBalance = salesRevenue + deposits - withdrawals;

    // --- FONDO GIOCO (Jackpot) ---
    // Calcoliamo il montepremi basandoci sugli incassi EFFETTIVI dei giochi (categoria tombola/analotto)
    // NOTA: Come da logica App.tsx, quando si compra un ticket (es. 5€), 5€ vanno in category='tombola' e 1€ (20%) va in category='bar'.
    // Quindi il "Jackpot" accumulato è l'80% dei depositi totali di quella categoria.
    const tombolaMovements = activeMovements.filter(m => m.category === 'tombola');
    const analottoMovements = activeMovements.filter(m => m.category === 'analotto');

    const depositsTombola = tombolaMovements.filter(m => m.type === 'deposit').reduce((sum, m) => sum + m.amount, 0) || 0;
    const depositsAnalotto = analottoMovements.filter(m => m.type === 'deposit').reduce((sum, m) => sum + m.amount, 0) || 0;

    // Sottraiamo eventuali prelievi dal fondo gioco (es. rimborsi o vincite pagate cash se gestite così)
    const withdrawalsTombola = tombolaMovements.filter(m => m.type === 'withdrawal').reduce((sum, m) => sum + m.amount, 0) || 0;
    const withdrawalsAnalotto = analottoMovements.filter(m => m.type === 'withdrawal').reduce((sum, m) => sum + m.amount, 0) || 0;

    // Il fondo netto è (Incasso - Prelievi) * 0.80. 
    // Tuttavia, per semplicità e coerenza con la visualizzazione "incasso grezzo", mostriamo il totale dei depositi validi per il jackpot.
    const jackpotTombola = (depositsTombola - withdrawalsTombola) * 0.8;
    const jackpotAnalotto = (depositsAnalotto - withdrawalsAnalotto) * 0.8;
    const totalJackpotFund = jackpotTombola + jackpotAnalotto;

    const handleSubmitWithdrawal = async (e: React.FormEvent) => {
        e.preventDefault();
        const val = parseFloat(amount);
        if (!val || !reason.trim()) return;
        await onAddMovement({ amount: val, reason: reason.trim(), timestamp: new Date().toISOString(), type: 'withdrawal', category: 'bar' });
        setAmount(''); setReason('');
    };

    const handleSubmitMisc = async (e: React.FormEvent) => {
        e.preventDefault();
        const val = parseFloat(miscAmount);
        if (!val || !miscReason.trim()) return;
        await onAddMovement({ amount: val, reason: `SPESA VARIA: ${miscReason.trim()}`, timestamp: new Date().toISOString(), type: 'withdrawal', category: 'bar' });
        setMiscAmount(''); setMiscReason('');
    };

    const handleResetBar = async () => { 
        if(window.confirm("SEI SICURO? Questo azzererà il conteggio della cassa BAR.")) await onResetCash('bar'); 
    };

    const handleResetGames = async () => {
        if(window.confirm("ATTENZIONE: Azzerare il fondo giochi porterà a 0 anche i montepremi visibili nella Tombola e Analotto. Procedere?")) {
            await onResetCash('games');
        }
    };

    const handleSoftDelete = async (id: string) => {
        if (!currentUser?.email) return alert("Devi essere loggato per eliminare.");
        if (window.confirm("Vuoi spostare questo movimento nel cestino (annullare)?")) {
            await onDeleteMovement(id, currentUser.email);
        }
    };

    const handleHardDelete = async (id: string) => {
        if (!isSuperAdmin) return;
        if (window.confirm("ELIMINAZIONE DEFINITIVA. Il record sparirà dal database per sempre. Sei sicuro?")) {
            await onPermanentDeleteMovement(id);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                {/* SALDO BAR */}
                <div className="bg-slate-800 p-6 rounded-xl text-white relative overflow-hidden shadow-lg">
                    <p className="text-xs text-slate-400 uppercase font-bold tracking-wider">Saldo Operativo Bar</p>
                    <p className="text-4xl font-black mt-1">€{(operationalBalance || 0).toFixed(2)}</p>
                    <div className="mt-4 flex gap-4 text-xs opacity-80">
                        <span>Vendite: +€{(salesRevenue || 0).toFixed(2)}</span>
                        <span>Spese: -€{(withdrawals || 0).toFixed(2)}</span>
                    </div>
                    {isSuperAdmin && <button onClick={handleResetBar} className="absolute top-4 right-4 text-[10px] bg-red-600 px-2 py-1 rounded hover:bg-red-500 font-bold">RESET</button>}
                </div>

                {/* FONDO GIOCHI */}
                <div className="bg-indigo-700 p-6 rounded-xl text-white shadow-lg relative overflow-hidden">
                    <p className="text-xs text-indigo-300 uppercase font-bold tracking-wider">Fondo Gioco (Montepremi)</p>
                    <p className="text-4xl font-black mt-1">€{(totalJackpotFund || 0).toFixed(2)}</p>
                    <div className="mt-4 flex flex-col gap-1 text-xs opacity-80">
                        <div className="flex justify-between w-full pr-12">
                            <span>Tombola: €{(jackpotTombola || 0).toFixed(2)}</span>
                            <span>Analotto: €{(jackpotAnalotto || 0).toFixed(2)}</span>
                        </div>
                    </div>
                    {isSuperAdmin && <button onClick={handleResetGames} className="absolute top-4 right-4 text-[10px] bg-red-600 px-2 py-1 rounded hover:bg-red-500 font-bold">RESET</button>}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex items-center gap-2"><span className="text-red-500">▼</span> Prelievo / Versamento</h3>
                    <form onSubmit={handleSubmitWithdrawal} className="flex flex-col gap-3">
                        <input type="number" placeholder="Importo (€)" value={amount} onChange={e => setAmount(e.target.value)} className="bg-slate-50 border rounded-lg p-3 outline-none focus:ring-2 focus:ring-red-200" step="0.01" required />
                        <input type="text" placeholder="Causale (es. Versamento Banca)" value={reason} onChange={e => setReason(e.target.value)} className="bg-slate-50 border rounded-lg p-3 outline-none focus:ring-2 focus:ring-red-200" required />
                        <button type="submit" className="bg-red-500 hover:bg-red-600 text-white font-bold py-3 rounded-lg transition-colors">Registra Operazione</button>
                    </form>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                    <h3 className="font-bold text-slate-800 mb-4 border-b pb-2 flex items-center gap-2"><span className="text-orange-500">▼</span> Acquisti Vari</h3>
                    <form onSubmit={handleSubmitMisc} className="flex flex-col gap-3">
                        <input type="number" placeholder="Costo (€)" value={miscAmount} onChange={e => setMiscAmount(e.target.value)} className="bg-slate-50 border rounded-lg p-3 outline-none focus:ring-2 focus:ring-orange-200" step="0.01" required />
                        <input type="text" placeholder="Descrizione (es. Cancelleria, Ghiaccio)" value={miscReason} onChange={e => setMiscReason(e.target.value)} className="bg-slate-50 border rounded-lg p-3 outline-none focus:ring-2 focus:ring-orange-200" required />
                        <button type="submit" className="bg-orange-500 hover:bg-orange-600 text-white font-bold py-3 rounded-lg transition-colors">Registra Spesa</button>
                    </form>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <h3 className="font-bold text-slate-800 p-4 bg-slate-50 border-b border-slate-200">Storico Movimenti Completo</h3>
                <div className="max-h-80 overflow-y-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-slate-50 text-slate-500 sticky top-0 text-xs uppercase"><tr><th className="p-3">Data</th><th className="p-3">Causale</th><th className="p-3">Cat.</th><th className="p-3 text-right">Importo</th><th className="p-3 text-center">Azioni</th></tr></thead>
                        <tbody className="divide-y divide-slate-100">
                            {movements.map(m => (
                                <tr key={m.id} className={`hover:bg-slate-50 ${m.isDeleted ? 'bg-red-50 opacity-50' : ''}`}>
                                    <td className="p-3 text-xs text-slate-400 whitespace-nowrap">
                                        {new Date(m.timestamp).toLocaleString()}
                                        {m.isDeleted && <div className="text-[9px] text-red-500">DEL: {m.deletedBy}</div>}
                                    </td>
                                    <td className="p-3 font-medium text-slate-700">{m.reason}</td>
                                    <td className="p-3 text-xs uppercase font-bold text-slate-400">{m.category || 'BAR'}</td>
                                    <td className={`p-3 text-right font-bold ${m.type === 'withdrawal' ? 'text-red-500' : 'text-green-500'}`}>
                                        {m.type === 'withdrawal' ? '-' : '+'}€{m.amount.toFixed(2)}
                                    </td>
                                    <td className="p-3 flex justify-center gap-2">
                                        {!m.isDeleted && (
                                            <button onClick={() => handleSoftDelete(m.id)} className="text-red-300 hover:text-red-500 p-1 rounded hover:bg-red-50" title="Annulla Movimento">
                                                <TrashIcon className="h-4 w-4" />
                                            </button>
                                        )}
                                        {isSuperAdmin && (
                                            <button onClick={() => handleHardDelete(m.id)} className="text-red-800 hover:text-red-600 bg-red-100 hover:bg-red-200 p-1 rounded" title="ELIMINA DEFINITIVAMENTE">
                                                <span className="font-bold text-xs px-1">X</span>
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};
export default CashManagement;

import { db } from '../firebaseConfig';
import { AnalottoConfig, AnalottoBet, AnalottoExtraction, AnalottoWheel } from '../types';
import firebase from 'firebase/compat/app';

export const AnalottoService = {
    // --- LISTENERS ---

    subscribeToConfig: (onUpdate: (config: AnalottoConfig) => void) => {
        return db.collection('analotto').doc('config').onSnapshot((snapshot) => {
            if (snapshot.exists) {
                onUpdate(snapshot.data() as AnalottoConfig);
            } else {
                const initialConfig: AnalottoConfig = { 
                    jackpot: 0, 
                    lastExtraction: '',
                    rules: "Regolamento Analotto VVF:\n1. Si scelgono da 1 a 10 numeri.\n2. Si sceglie su quali ruote puntare.\n3. L'estrazione avviene settimanalmente.\n4. Il montepremi è costituito dall'80% delle giocate.",
                    extractionSchedule: "Ogni Venerdì sera"
                };
                db.collection('analotto').doc('config').set(initialConfig);
            }
        });
    },

    subscribeToBets: (onUpdate: (bets: AnalottoBet[]) => void) => {
        return db.collection('analotto_bets').orderBy('timestamp', 'desc').onSnapshot((snapshot) => {
            const bets = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as AnalottoBet));
            onUpdate(bets);
        });
    },

    subscribeToExtractions: (onUpdate: (extractions: AnalottoExtraction[]) => void) => {
        return db.collection('analotto_extractions').orderBy('timestamp', 'desc').onSnapshot((snapshot) => {
            const extractions = snapshot.docs.map(d => ({ ...d.data(), id: d.id } as AnalottoExtraction));
            onUpdate(extractions);
        });
    },

    placeBet: async (bet: Omit<AnalottoBet, 'id' | 'timestamp'>) => {
        await db.runTransaction(async (t) => {
            const configRef = db.collection('analotto').doc('config');
            const configDoc = await t.get(configRef);
            const currentConfig = configDoc.data() as AnalottoConfig;

            const betRef = db.collection('analotto_bets').doc();
            t.set(betRef, {
                ...bet,
                timestamp: new Date().toISOString()
            });

            if (bet.status === 'active') {
                // Update Jackpot (80% of bet)
                const jackpotAdd = bet.amount * 0.8;
                const revenueAdd = bet.amount * 0.2;
                t.update(configRef, { jackpot: (currentConfig.jackpot || 0) + jackpotAdd });

                // Cash Movements
                const cashRef = db.collection('cash_movements').doc();
                t.set(cashRef, {
                    amount: bet.amount,
                    reason: `Analotto: Giocata ${bet.playerName}`,
                    timestamp: new Date().toISOString(),
                    type: 'deposit',
                    category: 'analotto'
                });

                const barCashRef = db.collection('cash_movements').doc();
                t.set(barCashRef, {
                    amount: revenueAdd,
                    reason: `Utile Analotto (20%)`,
                    timestamp: new Date().toISOString(),
                    type: 'deposit',
                    category: 'bar'
                });
            }
        });
    },

    confirmTicket: async (ticketId: string, numbers: number[], wheels: AnalottoWheel[]) => {
        await db.runTransaction(async (t) => {
            const ticketRef = db.collection('analotto_bets').doc(ticketId);
            const ticketDoc = await t.get(ticketRef);
            if (!ticketDoc.exists) throw new Error("Ticket not found");
            const ticket = ticketDoc.data() as AnalottoBet;

            if (ticket.status !== 'pending') throw new Error("Ticket already active");

            const configRef = db.collection('analotto').doc('config');
            const configDoc = await t.get(configRef);
            const currentConfig = configDoc.data() as AnalottoConfig;

            t.update(ticketRef, {
                status: 'active',
                numbers,
                wheels,
                timestamp: new Date().toISOString() // Update time to activation
            });

            // Update Jackpot
            const jackpotAdd = ticket.amount * 0.8;
            const revenueAdd = ticket.amount * 0.2;
            t.update(configRef, { jackpot: (currentConfig.jackpot || 0) + jackpotAdd });

            // Cash movements
            const cashRef = db.collection('cash_movements').doc();
            t.set(cashRef, {
                amount: ticket.amount,
                reason: `Analotto: Completamento Ticket ${ticket.playerName}`,
                timestamp: new Date().toISOString(),
                type: 'deposit',
                category: 'analotto'
            });

            const barCashRef = db.collection('cash_movements').doc();
            t.set(barCashRef, {
                amount: revenueAdd,
                reason: `Utile Analotto (20%)`,
                timestamp: new Date().toISOString(),
                type: 'deposit',
                category: 'bar'
            });
        });
    },

    runExtraction: async () => {
        const wheels: AnalottoWheel[] = ['APS', 'Campagnola', 'Autoscala', 'Autobotte', 'Direttivo'];
        const extractionData: any = {};

        wheels.forEach(w => {
            const nums: number[] = [];
            while(nums.length < 5) {
                const n = Math.floor(Math.random() * 90) + 1;
                if(!nums.includes(n)) nums.push(n);
            }
            extractionData[w] = nums.sort((a,b) => a-b);
        });

        await db.runTransaction(async (t) => {
            const configRef = db.collection('analotto').doc('config');

            const extractionRef = db.collection('analotto_extractions').doc();
            t.set(extractionRef, {
                timestamp: new Date().toISOString(),
                numbers: extractionData
            });

            t.update(configRef, { lastExtraction: new Date().toISOString() });
        });
    },

    updateConfig: async (cfg: Partial<AnalottoConfig>) => {
        await db.collection('analotto').doc('config').set(cfg, { merge: true });
    },

    transferFunds: async (amount: number) => {
        await db.runTransaction(async (t) => {
            const configRef = db.collection('analotto').doc('config');
            t.update(configRef, { jackpot: 0 });

            const cashRef = db.collection('cash_movements').doc();
            t.set(cashRef, {
                amount: amount,
                reason: `Versamento utile Analotto`,
                timestamp: new Date().toISOString(),
                type: 'deposit',
                category: 'bar',
                isDeleted: false
            });
        });
    }
};

import { db } from '../firebaseConfig';
import { TombolaConfig, TombolaTicket, TombolaWin } from '../types';

// Helper per mescolare un array (necessario per generare le cartelle)
const shuffleArray = (array: any[]) => {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
};

// Helper per generare una cartella singola valida
const generateSingleTicket = () => {
    const ticket: number[] = [];
    const cols: number[][] = Array.from({ length: 9 }, () => []);
    for (let i = 0; i < 9; i++) {
        const start = i * 10 + 1;
        const end = i === 8 ? 90 : (i + 1) * 10;
        for(let n=start; n <= end; n++) if(i===0 && n>9) continue; else cols[i].push(n);
    }
    let numbersCount = 0;
    while(numbersCount < 15) {
        const colIdx = Math.floor(Math.random() * 9);
        if(cols[colIdx].length > 0) {
            const numIdx = Math.floor(Math.random() * cols[colIdx].length);
            const num = cols[colIdx][numIdx];
            if(!ticket.includes(num)) {
                ticket.push(num);
                cols[colIdx].splice(numIdx, 1);
                numbersCount++;
            }
        }
    }
    return ticket.sort((a,b) => a-b);
};

export const TombolaService = {
    // --- LISTENERS ---

    subscribeToConfig: (onUpdate: (config: TombolaConfig) => void) => {
        return db.collection('tombola').doc('config').onSnapshot((snapshot) => {
            if (snapshot.exists) {
                onUpdate(snapshot.data() as TombolaConfig);
            } else {
                const initialConfig: TombolaConfig = { 
                    status: 'pending',
                    maxTickets: 168,
                    minTicketsToStart: 84,
                    ticketPriceSingle: 2,
                    ticketPriceBundle: 5,
                    jackpot: 0, 
                    lastExtraction: new Date().toISOString(), 
                    extractedNumbers: [] 
                };
                db.collection('tombola').doc('config').set(initialConfig);
            }
        });
    },

    subscribeToTickets: (onUpdate: (tickets: TombolaTicket[]) => void) => {
        return db.collection('tombola_tickets').onSnapshot((snapshot) => {
            const tickets = snapshot.docs.map(d => ({...d.data(), id: d.id} as TombolaTicket));
            onUpdate(tickets);
        });
    },

    subscribeToWins: (onUpdate: (wins: TombolaWin[]) => void) => {
        return db.collection('tombola_wins').onSnapshot((snapshot) => {
            const wins = snapshot.docs.map(d => ({...d.data(), id: d.id} as TombolaWin));
            onUpdate(wins);
        });
    },

    // --- ACTIONS ---

    buyTicket: async (playerId: string, playerName: string, quantity: number) => {
        try {
            await db.runTransaction(async (t) => {
                const configRef = db.collection('tombola').doc('config');
                const configSnap = await t.get(configRef);
                if (!configSnap.exists) throw new Error("Configurazione Tombola mancante");
                const currentConfig = configSnap.data() as TombolaConfig;

                let totalCost = 0;
                let pricePerTicket = 0;

                if (quantity === 6) {
                    totalCost = currentConfig.ticketPriceBundle;
                    pricePerTicket = totalCost / 6;
                } else {
                    totalCost = quantity * currentConfig.ticketPriceSingle;
                    pricePerTicket = currentConfig.ticketPriceSingle;
                }

                const revenue = totalCost * 0.20;
                const jackpotAdd = totalCost * 0.80;

                // Generazione Cartelle
                if (quantity === 6) {
                    const allNumbers = shuffleArray(Array.from({ length: 90 }, (_, i) => i + 1));
                    for (let i = 0; i < 6; i++) {
                        const ticketNumbers = allNumbers.slice(i * 15, (i + 1) * 15).sort((a: number, b: number) => a - b);
                        const ticketRef = db.collection('tombola_tickets').doc();
                        t.set(ticketRef, { 
                            playerId, 
                            playerName, 
                            numbers: ticketNumbers, 
                            purchaseTime: new Date().toISOString(), 
                            pricePaid: pricePerTicket 
                        });
                    }
                } else {
                    for (let i = 0; i < quantity; i++) {
                        const ticketNumbers = generateSingleTicket();
                        const ticketRef = db.collection('tombola_tickets').doc();
                        t.set(ticketRef, { 
                            playerId, 
                            playerName, 
                            numbers: ticketNumbers, 
                            purchaseTime: new Date().toISOString(),
                            pricePaid: pricePerTicket
                        });
                    }
                }

                t.update(configRef, { jackpot: (currentConfig.jackpot || 0) + jackpotAdd });

                const cashRef = db.collection('cash_movements').doc();
                t.set(cashRef, { 
                    amount: totalCost, 
                    reason: `Tombola: ${quantity} cartelle (${playerName})`, 
                    timestamp: new Date().toISOString(), 
                    type: 'deposit', 
                    category: 'tombola' 
                });

                const barCashRef = db.collection('cash_movements').doc();
                t.set(barCashRef, { 
                    amount: revenue, 
                    reason: `Utile Tombola (20%)`, 
                    timestamp: new Date().toISOString(), 
                    type: 'deposit', 
                    category: 'bar' 
                });
            });
        } catch (e) {
            console.error("TombolaService: Errore acquisto", e);
            throw e;
        }
    },

    refundTicket: async (ticketId: string) => {
        try {
            await db.runTransaction(async (t) => {
                const configRef = db.collection('tombola').doc('config');
                const configSnap = await t.get(configRef);
                if (!configSnap.exists) throw new Error("Configurazione Tombola mancante");
                const currentConfig = configSnap.data() as TombolaConfig;

                if (currentConfig.status === 'active' || currentConfig.status === 'completed') {
                    throw new Error("Impossibile annullare cartelle a gioco iniziato.");
                }

                const ticketRef = db.collection('tombola_tickets').doc(ticketId);
                const ticketSnap = await t.get(ticketRef);
                if (!ticketSnap.exists) throw new Error("Cartella non trovata");

                const ticketData = ticketSnap.data() as TombolaTicket;
                const refundAmount = ticketData.pricePaid !== undefined ? ticketData.pricePaid : currentConfig.ticketPriceSingle;
                const jackpotDeduction = refundAmount * 0.80;
                const revenueDeduction = refundAmount * 0.20;

                t.delete(ticketRef);
                t.update(configRef, { jackpot: Math.max(0, (currentConfig.jackpot || 0) - jackpotDeduction) });

                const cashRef = db.collection('cash_movements').doc();
                t.set(cashRef, { amount: refundAmount, reason: "Rimborso Cartella (Annullamento)", timestamp: new Date().toISOString(), type: 'withdrawal', category: 'tombola' });

                const barCashRef = db.collection('cash_movements').doc();
                t.set(barCashRef, { amount: revenueDeduction, reason: "Storno Utile Tombola (Rimborso)", timestamp: new Date().toISOString(), type: 'withdrawal', category: 'bar' });
            });
        } catch (e) {
            console.error("TombolaService: Errore rimborso", e);
            throw e;
        }
    },

    manualExtraction: async () => {
        try {
            await db.runTransaction(async (t) => {
                const configRef = db.collection('tombola').doc('config');
                const configSnap = await t.get(configRef);
                const currentConfig = configSnap.data() as TombolaConfig;

                if (currentConfig.status !== 'active') return;
                if (!currentConfig.extractedNumbers) currentConfig.extractedNumbers = [];
                if (currentConfig.extractedNumbers.length >= 90) return;

                let nextNum;
                do { nextNum = Math.floor(Math.random() * 90) + 1; } while (currentConfig.extractedNumbers.includes(nextNum));

                const newExtracted = [...currentConfig.extractedNumbers, nextNum];

                // Fetch tickets outside of transaction or assume small dataset? 
                // Firestore transaction requires reads before writes. 
                // Reading ALL tickets might be too much. 
                // But for VVF Tombola (max 168 tickets), it's fine.
                const ticketsSnap = await t.get(db.collection('tombola_tickets'));

                ticketsSnap.forEach(ticketDoc => {
                    const ticket = ticketDoc.data() as TombolaTicket;
                    if (!ticket.numbers) return;

                    const matches = ticket.numbers.filter(n => newExtracted.includes(n));
                    const count = matches.length;

                    if ([2,3,4,5,15].includes(count)) {
                        const type = count === 2 ? 'Ambo' : count === 3 ? 'Terno' : count === 4 ? 'Quaterna' : count === 5 ? 'Cinquina' : 'Tombola';

                        // Note: ideally check if already won this type
                        const winRef = db.collection('tombola_wins').doc();
                        t.set(winRef, { 
                            ticketId: ticketDoc.id, 
                            playerName: ticket.playerName, 
                            type, 
                            numbers: matches, 
                            timestamp: new Date().toISOString() 
                        });
                    }
                });

                t.update(configRef, { lastExtraction: new Date().toISOString(), extractedNumbers: newExtracted });
            });
        } catch (e) {
            console.error("TombolaService: Errore estrazione", e);
        }
    },

    startGame: async () => {
        await db.collection('tombola').doc('config').update({ 
            status: 'active', 
            lastExtraction: new Date().toISOString() 
        });
    },

    updateConfig: async (cfg: Partial<TombolaConfig>) => {
        await db.collection('tombola').doc('config').set(cfg, { merge: true });
    },

    transferFunds: async (amount: number) => {
        if (amount <= 0) return;
        try {
            await db.runTransaction(async (t) => {
                t.update(db.collection('tombola').doc('config'), { jackpot: 0 });
                const cashRef = db.collection('cash_movements').doc();
                t.set(cashRef, { 
                    amount: amount, 
                    reason: `Versamento utile Tombola`, 
                    timestamp: new Date().toISOString(), 
                    type: 'deposit', 
                    category: 'bar', 
                    isDeleted: false 
                });
            });
        } catch (error) { 
            console.error("TombolaService: Error transferring funds", error); 
            throw error;
        }
    }
};

import { db } from '../firebaseConfig';
import { Product, StaffMember, Order, CashMovement, TillColors, SeasonalityConfig, ShiftSettings, GeneralSettings, AttendanceRecord, AdminUser, AppNotification } from '../types';

export const BarService = {
    // --- LISTENERS ---

    subscribeToProducts: (onUpdate: (data: Product[]) => void) => {
        return db.collection('products').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as Product))));
    },

    subscribeToStaff: (onUpdate: (data: StaffMember[]) => void) => {
        return db.collection('staff').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as StaffMember))));
    },

    subscribeToOrders: (onUpdate: (data: Order[]) => void) => {
        return db.collection('orders').orderBy('timestamp', 'desc').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as Order))));
    },

    subscribeToCashMovements: (onUpdate: (data: CashMovement[]) => void) => {
        return db.collection('cash_movements').orderBy('timestamp', 'desc').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as CashMovement))));
    },

    subscribeToAdmins: (onUpdate: (data: AdminUser[]) => void) => {
        return db.collection('admins').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as AdminUser))));
    },

    subscribeToNotifications: (onUpdate: (data: AppNotification | null) => void) => {
        const sessionStart = new Date().toISOString();
        return db.collection('notifications')
            .where('timestamp', '>', sessionStart)
            .orderBy('timestamp', 'desc')
            .onSnapshot((snapshot) => {
                snapshot.docChanges().forEach((change) => {
                    if (change.type === 'added') {
                        onUpdate(change.doc.data() as AppNotification);
                    }
                });
            });
    },

    // --- SETTINGS LISTENERS ---

    subscribeToTillColors: (onUpdate: (data: TillColors) => void) => {
        return db.collection('settings').doc('tillColors').onSnapshot((d) => { if(d.exists) onUpdate(d.data() as TillColors); });
    },

    subscribeToSeasonality: (onUpdate: (data: SeasonalityConfig) => void) => {
        return db.collection('settings').doc('seasonality').onSnapshot((d) => { 
            if(d.exists) onUpdate(d.data() as SeasonalityConfig);
            else db.collection('settings').doc('seasonality').set({ startDate: '', endDate: '', preset: 'custom', animationType: 'none', emojis: [], opacity: 0.5, backgroundColor: '#f8fafc' });
        });
    },

    subscribeToShiftSettings: (onUpdate: (data: ShiftSettings) => void) => {
        return db.collection('settings').doc('shift').onSnapshot((d) => {
            if(d.exists) onUpdate(d.data() as ShiftSettings);
            else {
                db.collection('settings').doc('shift').set({ anchorDate: '2025-12-10', anchorShift: 'd', rcAnchorDate: '', rcAnchorShift: 'a', rcAnchorSubGroup: 1 });
            }
        });
    },

    subscribeToGeneralSettings: (onUpdate: (data: GeneralSettings) => void) => {
        return db.collection('settings').doc('general').onSnapshot((d) => {
            if (d.exists) onUpdate(d.data() as GeneralSettings);
            else db.collection('settings').doc('general').set({ waterQuotaPrice: 0 });
        });
    },

    subscribeToAttendance: (onUpdate: (data: AttendanceRecord[]) => void) => {
        return db.collection('shift_attendance').onSnapshot((s) => onUpdate(s.docs.map(d => ({ ...d.data(), id: d.id } as AttendanceRecord))));
    },

    // --- OPERATIONS ---

    // Orders
    completeOrder: async (newOrderData: Omit<Order, 'id'>) => {
        try {
            await db.runTransaction(async (t) => {
                const productRefs = newOrderData.items.map(item => db.collection('products').doc(item.product.id));
                const productDocs = await Promise.all(productRefs.map(ref => t.get(ref)));

                productDocs.forEach((docSnap, index) => {
                    if (!docSnap.exists) throw new Error(`Prodotto non trovato.`);
                    const currentStock = Number(docSnap.data()?.stock) || 0;
                    t.update(productRefs[index], { stock: currentStock - newOrderData.items[index].quantity });
                });

                const orderRef = db.collection('orders').doc();
                t.set(orderRef, { ...newOrderData, id: orderRef.id });
            });
        } catch (error) { 
            console.error("BarService: Transazione Ordine Fallita:", error); 
            throw error; 
        }
    },

    updateOrder: async (order: Order) => {
        const { id, ...data } = order;
        await db.collection('orders').doc(id).update(data);
    },

    deleteOrders: async (ids: string[], userEmail: string) => {
        const batch = db.batch();
        ids.forEach(id => batch.update(db.collection('orders').doc(id), { isDeleted: true, deletedBy: userEmail, deletedAt: new Date().toISOString() }));
        await batch.commit();
    },

    permanentDeleteOrder: async (id: string) => {
        await db.collection('orders').doc(id).delete();
    },

    // Products
    addProduct: async (data: any, userEmail: string) => {
        await db.collection('products').add({ ...data, createdAt: new Date().toISOString(), createdBy: userEmail });
    },
    updateProduct: async (product: any) => {
        const { id, ...data } = product;
        await db.collection('products').doc(id).update(data);
    },
    deleteProduct: async (id: string) => {
        await db.collection('products').doc(id).delete();
    },

    // Stock
    stockPurchase: async (productId: string, quantity: number, cost: number) => {
        const pRef = db.collection('products').doc(productId);
        const pSnap = await pRef.get();
        if(pSnap.exists) {
            await pRef.update({ stock: pSnap.data()!.stock + quantity, costPrice: cost });
            await db.collection('cash_movements').add({ 
                amount: quantity * cost, 
                reason: `Acquisto Stock: ${pSnap.data()!.name}`, 
                timestamp: new Date().toISOString(), 
                type: 'withdrawal', 
                category: 'bar' 
            });
        }
    },

    stockCorrection: async (productId: string, stock: number) => {
        await db.collection('products').doc(productId).update({ stock });
    },

    // Staff
    addStaff: async (data: any) => { await db.collection('staff').add(data); },
    updateStaff: async (staff: any) => { const { id, ...data } = staff; await db.collection('staff').doc(id).update(data); },
    deleteStaff: async (id: string) => { await db.collection('staff').doc(id).delete(); },

    // Cash
    addCashMovement: async (data: any) => { await db.collection('cash_movements').add(data); },
    updateCashMovement: async (movement: any) => { const { id, ...data } = movement; await db.collection('cash_movements').doc(id).update(data); },
    deleteCashMovement: async (id: string, email: string) => { await db.collection('cash_movements').doc(id).update({ isDeleted: true, deletedBy: email, deletedAt: new Date().toISOString() }); },
    permanentDeleteMovement: async (id: string) => { await db.collection('cash_movements').doc(id).delete(); },

    resetCash: async (type: 'bar' | 'games', allMovements: CashMovement[]) => {
        const batch = db.batch();
        const movementsToReset = allMovements.filter(m => {
            if (type === 'bar') return (m.category === 'bar' || !m.category);
            if (type === 'games') return (m.category === 'tombola' || m.category === 'analotto');
            return false;
        });
        movementsToReset.forEach(m => batch.update(db.collection('cash_movements').doc(m.id), { amount: 0, reason: m.reason + ' (RESET)' }));
        if (type === 'games') {
            batch.update(db.collection('tombola').doc('config'), { jackpot: 0 });
            batch.update(db.collection('analotto').doc('config'), { jackpot: 0 });
        }
        await batch.commit();
    },

    // Admins
    addAdmin: async (email: string, addedBy: string) => { await db.collection('admins').add({ email, addedBy, timestamp: new Date().toISOString() }); },
    removeAdmin: async (id: string) => { await db.collection('admins').doc(id).delete(); },

    // Attendance
    saveAttendance: async (tillId: string, presentStaffIds: string[], dateOverride?: string) => {
        const dateToUse = dateOverride || new Date().toISOString().split('T')[0];
        const docId = `${dateToUse}_${tillId}`; 
        await db.collection('shift_attendance').doc(docId).set({ tillId, date: dateToUse, timestamp: new Date().toISOString(), presentStaffIds });
    },
    deleteAttendance: async (id: string) => { await db.collection('shift_attendance').doc(id).delete(); },

    // Settings & Notifications
    updateTillColors: async (c: TillColors) => { await db.collection('settings').doc('tillColors').set(c, { merge: true }); },
    updateSeasonality: async (cfg: SeasonalityConfig) => { await db.collection('settings').doc('seasonality').set(cfg); },
    updateShiftSettings: async (cfg: ShiftSettings) => { await db.collection('settings').doc('shift').set(cfg); },
    updateGeneralSettings: async (cfg: GeneralSettings) => { await db.collection('settings').doc('general').set(cfg, { merge: true }); },

    sendNotification: async (title: string, body: string, sender: string) => {
        await db.collection('notifications').add({ title, body, target: 'all', timestamp: new Date().toISOString(), sender });
    },

    // Utils
    massDelete: async (date: string, type: 'orders' | 'movements') => {
        const q = db.collection(type === 'orders' ? 'orders' : 'cash_movements').where('timestamp', '<=', new Date(date).toISOString());
        const s = await q.get();
        const batch = db.batch();
        s.docs.forEach(d => batch.delete(d.ref));
        await batch.commit();
    }
};
